tasks.check:
set -o pipefail
[ -e .venv ] || ln -s /home/bcorfman/dev/freytag-forge/.venv .venv
export PYTHONPATH=$PWD TMPDIR=/tmp
PY=.venv/bin/python
CH=$(git status --porcelain | grep -v '^?? .venv' | awk '{print $2}' | sort | tr '\n' ' ')
for f in $CH; do case "$f" in storygame/runtime/delivery_text.py|storygame/runtime/knowledge.py|storygame/runtime/recent_cue.py|storygame/personas.py|tests/test_delivery_variants.py) ;; *) echo "WHY: edited file outside ownership: $f"; exit 1;; esac; done
grep -q "def true_fact_ids" storygame/runtime/delivery_text.py || { echo "WHY: true_fact_ids helper missing"; exit 1; }
grep -c "true_fact_ids" storygame/runtime/knowledge.py storygame/runtime/recent_cue.py storygame/personas.py | grep -q ":0" && { echo "WHY: helper not used in all three call sites"; grep -c "true_fact_ids" storygame/runtime/knowledge.py storygame/runtime/recent_cue.py storygame/personas.py; exit 1; }
grep -n 'str(fact.value).lower() == "true"' storygame/runtime/recent_cue.py && { echo "WHY: recent_cue still has its own truth computation"; exit 1; }
$PY -m pytest -q -p no:cacheprovider tests/test_delivery_variants.py tests/test_knowledge_projection.py tests/test_candidate_matcher.py tests/test_cloudflare_transport.py tests/test_knowledge_leakage_matrix.py $(grep -l "personas\|recent_cue" tests/*.py | tr '\n' ' ') 2>&1 | tail -15
[ "${PIPESTATUS[0]}" = 0 ] || { echo "WHY: suites failed"; exit 1; }
$PY -m ruff format --check . && $PY -m ruff check . || { echo "WHY: ruff"; exit 1; }
OUT=/home/bcorfman/dev/ringer-work/act2-2c-yes
mkdir -p $OUT && git add -A -- . ':!.venv' && git diff --cached > $OUT/e1b.patch && wc -l $OUT/e1b.patch && git diff --cached --stat | tail -8
